+++ b/server/entitlement.ts
@@ -0,0 +1,115 @@
+/**
+ * Subscription entitlement gate for the hosted MCP server.
+ *
+ * ONE reconciled entitlement, read-only, used by every product path:
+ *   PAID  → user_subscriptions (Stripe-synced): status active|past_due
+ *           with a paid plan. past_due is honored as a dunning grace window
+ *           (Stripe retries; a final failure sends subscription.deleted →
+ *           cancelled → deny) so a paying customer's transient card failure
+ *           never hard-locks them.
+ *   TRIAL → the trial clock that registration actually writes:
+ *           users.trial_ends_at / cli_users.trial_ends_at (default NOW()+7d,
+ *           migration 031). We do NOT create or reset trials here — seeding a
+ *           fresh user_subscriptions trial would reset expired clocks (trial
+ *           abuse) and diverge from /v1/subscription/validate, which reads
+ *           these same columns.
+ *
+ * Fail CLOSED: any lookup error denies with a retryable message rather than
+ * grant — a paid product must never hand out access on an unverifiable state
+ * (CONSTITUTION.md — never fabricate entitlement).
+ *
+ * Keyed by the resolved owner id the transport already computed (users.id for
+ * a user key; projects.user_id — which may be a cli_users id — for a project
+ * key). Trial + paid are both looked up by that same id, so no key drift.
+ *
+ * Known limitation (tracked follow-up, not closed here): a user who connects
+ * via the CLI (cli_users.id) and pays via the dashboard (users.id) has two
+ * unlinked identities; the paid row may key to a different id than the CLI
+ * caller. Cross-identity account linking (by email) is its own task.
+ */
+
+import { supabaseServer } from './db-supabase'
+
+const PAID_TIERS = ['starter', 'professional', 'team', 'enterprise']
+// Statuses that mean "this is a real paying/converting customer — let them in".
+//  active   = paid & current
+//  past_due = card failed, Stripe is retrying (dunning grace — never hard-lock a payer)
+//  trialing = a Stripe-side trial on a real paid plan (coupon / trial_period_days).
+//             Guarded below by a paid plan_id so a bare row can't self-grant.
+const PAID_STATUSES = ['active', 'past_due', 'trialing']
+
+export interface Entitlement {
+  ok: boolean
+  reason: 'paid' | 'trialing' | 'trial_expired' | 'payment_required' | 'no_account' | 'error'
+  message: string
+  tier?: string
+  daysRemaining?: number
+}
+
+const UPGRADE = 'https://vasperamemory.com/pricing'
+
+export async function assertEntitled(userId: string): Promise<Entitlement> {
+  try {
+    // 1) PAID — the Stripe-synced source of truth
+    const { data: sub, error: subErr } = await supabaseServer
+      .from('user_subscriptions')
+      .select('status, plan_id')
+      .eq('user_id', userId)
+      .maybeSingle()
+    if (subErr) throw subErr
+
+    if (sub && PAID_STATUSES.includes(sub.status) && PAID_TIERS.includes(sub.plan_id ?? '')) {
+      return { ok: true, reason: 'paid', message: 'active', tier: sub.plan_id ?? undefined }
+    }
+    if (sub && (sub.status === 'cancelled' || sub.status === 'canceled')) {
+      return { ok: false, reason: 'payment_required', message: `Your subscription was cancelled. Reactivate at ${UPGRADE}.` }
+    }
+
+    // 2) TRIAL — the clock registration actually set (users OR cli_users)
+    const trialEndsAt = await lookupTrialEnd(userId)
+    if (trialEndsAt === null) {
+      // No account row and no paid sub — cannot establish entitlement. Deny.
+      return { ok: false, reason: 'no_account', message: 'No account found. Run `npx vasperamemory connect`.' }
+    }
+    const now = Date.now()
+    const endMs = Date.parse(trialEndsAt)
+    if (Number.isFinite(endMs) && now <= endMs) {
+      return {
+        ok: true,
+        reason: 'trialing',
+        message: 'trialing',
+        tier: 'free_trial',
+        daysRemaining: Math.max(0, Math.ceil((endMs - now) / 86_400_000)),
+      }
+    }
+    return { ok: false, reason: 'trial_expired', message: `Your free trial has ended. Upgrade at ${UPGRADE} to keep using VasperaMemory.` }
+  } catch (err) {
+    console.error('[entitlement] verification failed, denying:', err instanceof Error ? err.message : err)
+    return { ok: false, reason: 'error', message: 'Could not verify your subscription right now. Please try again in a moment.' }
+  }
+}
+
+/** trial_ends_at for the id from users, else cli_users. null if neither exists. */
+async function lookupTrialEnd(userId: string): Promise<string | null> {
+  const { data: webUser } = await supabaseServer
+    .from('users')
+    .select('trial_ends_at, created_at')
+    .eq('id', userId)
+    .maybeSingle()
+  if (webUser) return webUser.trial_ends_at ?? fallbackTrialEnd(webUser.created_at)
+
+  const { data: cliUser } = await supabaseServer
+    .from('cli_users')
+    .select('trial_ends_at, created_at')
+    .eq('id', userId)
+    .maybeSingle()
+  if (cliUser) return cliUser.trial_ends_at ?? fallbackTrialEnd(cliUser.created_at)
+
+  return null
+}
+
+/** For rows predating the trial_ends_at default: created_at + 7 days. */
+function fallbackTrialEnd(createdAt: string | null): string {
+  const base = createdAt ? Date.parse(createdAt) : Date.now()
+  return new Date((Number.isFinite(base) ? base : Date.now()) + 7 * 86_400_000).toISOString()
+}
