+/**
+ * requireAuth + subscription gate in one. Returns the authenticated user, or
+ * null after sending 401 (missing/invalid key) or 402 (unpaid/expired trial).
+ * Every PAID product route — memory reads/writes, ai-learning, CLI project
+ * sync — must use this. requireAuth alone only proves identity; it does NOT
+ * check entitlement, so a route guarded by requireAuth only is a revenue leak
+ * (an expired-trial user with a valid key still gets the product). Reason
+ * codes + upgrade URL mirror server/mcp-memory.ts requireEntitled.
+ */
+export async function requireEntitled(
+  req: FastifyRequest,
+  reply: FastifyReply
+): Promise<{ id: string; email?: string } | null> {
+  const user = await requireAuth(req.headers)
+  if (!user) {
+    reply.code(401).send({ error: 'unauthorized' })
+    return null
+  }
+  const gate = await assertEntitled(user.id)
+  if (!gate.ok) {
+    reply.code(402).send({
+      error: 'payment_required',
+      reason: gate.reason,
+      message: gate.message,
+      upgradeUrl: 'https://vasperamemory.com/pricing',
+    })
+    return null
+  }
+  return user as { id: string; email?: string }
+}
