+/**
+ * Real MCP handshake against POST /mcp/sse (the native-HTTP endpoint the
+ * configs point at): initialize → notifications/initialized → tools/list.
+ * Returns ok only if the server returns a non-empty tool list — the honest
+ * "did it actually work" check, instead of trusting that writing a config file
+ * means the client will connect.
+ */
+async function verifyMcpConnection(
+  serverUrl: string,
+  apiKey: string,
+  projectId?: string
+): Promise<{ ok: boolean; toolCount?: number; error?: string }> {
+  const url = `${serverUrl}/mcp/sse`;
+  const headers: Record<string, string> = {
+    'Content-Type': 'application/json',
+    'Authorization': `Bearer ${apiKey}`,
+    'X-Project-Id': projectId || ''
+  };
+  try {
+    const initRes = await fetch(url, {
+      method: 'POST',
+      headers,
+      body: JSON.stringify({
+        jsonrpc: '2.0', id: 1, method: 'initialize',
+        params: { protocolVersion: '2024-11-05', capabilities: {}, clientInfo: { name: 'vasperamemory-cli', version: CLI_VERSION } }
+      })
+    });
+    if (initRes.status === 401) return { ok: false, error: 'unauthorized (401) — API key not accepted' };
+    if (initRes.status === 402) return { ok: false, error: 'payment required (402) — subscription/trial inactive' };
+    if (!initRes.ok) return { ok: false, error: `initialize returned HTTP ${initRes.status}` };
+    const initJson: any = await initRes.json();
+    if (!initJson?.result?.serverInfo) return { ok: false, error: 'initialize returned no serverInfo' };
+
+    // Notification — server should 202 and return no body.
+    await fetch(url, {
+      method: 'POST', headers,
+      body: JSON.stringify({ jsonrpc: '2.0', method: 'notifications/initialized' })
+    }).catch(() => {});
+
+    const toolsRes = await fetch(url, {
+      method: 'POST', headers,
+      body: JSON.stringify({ jsonrpc: '2.0', id: 2, method: 'tools/list' })
+    });
+    if (toolsRes.status === 402) return { ok: false, error: 'payment required (402) — subscription/trial inactive' };
+    if (!toolsRes.ok) return { ok: false, error: `tools/list returned HTTP ${toolsRes.status}` };
+    const toolsJson: any = await toolsRes.json();
+    const tools = toolsJson?.result?.tools;
+    if (!Array.isArray(tools) || tools.length === 0) return { ok: false, error: 'tools/list returned no tools' };
+    return { ok: true, toolCount: tools.length };
+  } catch (e: any) {
+    return { ok: false, error: e?.message || String(e) };
+  }
+}
