-
-      // Validate authorization code
-      const authResult = await oauthProvider.validateAuthorizationCode(
-        code,
-        client_id,
-        redirect_uri,
-        code_verifier
-      )
-
-      if (!authResult) {
-        return res.status(400).json({
-          error: 'invalid_grant',
-          error_description: 'Invalid authorization code'
-        })
-      }
-
-      // Generate tokens
-      const tokens = await oauthProvider.generateTokens({
-        user_id: authResult.user_id,
-        client_id,
-        scope: authResult.scope
-      })
-
-      res.json(tokens)
-    } else if (grant_type === 'refresh_token') {
-      // Validate client
-      const isValidClient = await oauthProvider.validateClient(client_id, client_secret)
-      if (!isValidClient) {
-        return res.status(401).json({
-          error: 'invalid_client',
-          error_description: 'Client authentication failed'
-        })
-      }
-
-      // Refresh token
-      const tokens = await oauthProvider.refreshAccessToken(refresh_token, client_id)
