-  private async getMetrics(): Promise<DashboardMetrics> {
-    // Use cache if still fresh (5 minutes)
-    if (this.metricsCache && (Date.now() - this.lastCacheUpdate.getTime()) < 5 * 60 * 1000) {
-      return this.metricsCache;
-    }
-
-    const analytics = await this.teamIntelligence.getTeamAnalytics();
-    
-    const metrics: DashboardMetrics = {
-      teamOverview: {
-        totalMembers: analytics.teamSize,
-        activeMembers: this.calculateActiveMembers(analytics.topContributors),
-        expertiseAreasCount: analytics.expertiseAreas.length,
-        knowledgeGapsCount: analytics.knowledgeGaps.length,
-        avgContributionScore: this.calculateAverageContribution(analytics.topContributors)
-      },
-      expertiseMap: analytics.expertiseAreas.map((area: any) => ({
-        domain: area.domain,
-        expertCount: area.expertMembers.length,
-        confidenceScore: area.confidenceScore,
-        recentActivity: area.recentActivity,
-        topExperts: area.expertMembers.slice(0, 3).map((id: string) => {
-          const member = analytics.topContributors.find((m: any) => m.id === id);
-          return {
-            id,
-            name: member?.name || 'Unknown',
-            score: member?.contributionScore || 0
-          };
-        })
-      })),
-      knowledgeGaps: analytics.knowledgeGaps.map((gap: any) => ({
-        id: gap.id,
-        domain: gap.domain,
-        severity: gap.severity,
-        affectedProjects: gap.affectedProjects,
-        suggestedActions: [
-          ...gap.suggestedExperts,
-          ...gap.learningResources.slice(0, 2)
-        ]
-      })),
-      onboardingProgress: {
-        activePaths: analytics.activeOnboarding,
-        avgCompletionRate: 0.75, // Placeholder - would calculate from actual progress
-        upcomingMilestones: [] // Placeholder - would fetch from onboarding paths
-      },
-      collectiveLearning: {
-        strongPatterns: analytics.collectiveLearning
-          .filter((p: any) => p.adoptionRate > 0.5)
-          .slice(0, 10)
-          .map((p: any) => ({
-            patternId: p.patternId,
-            description: `Pattern adopted by ${(p.adoptionRate * 100).toFixed(0)}% of team`,
-            adoptionRate: p.adoptionRate,
-            successRate: p.successRate
-          })),
-        emergingPatterns: analytics.collectiveLearning
-          .filter((p: any) => p.adoptionRate <= 0.5 && p.adoptionRate > 0.2)
-          .slice(0, 5)
-          .map((p: any) => ({
-            patternId: p.patternId,
-            description: `Emerging pattern with ${p.adopters.length} adopters`,
-            adopters: p.adopters.length,
-            potential: p.reinforcementScore
-          }))
-      },
-      teamHealth: await this.calculateTeamHealth()
-    };
-
-    this.metricsCache = metrics;
-    this.lastCacheUpdate = new Date();
-    
-    return metrics;
-  }
