-  private calculateActiveMembers(contributors: any[]): number {
-    return contributors.filter(c => c.activityLevel > 0).length;
-  }
-
-  private calculateAverageContribution(contributors: any[]): number {
-    if (contributors.length === 0) return 0;
-    const sum = contributors.reduce((total, c) => total + c.contributionScore, 0);
-    return sum / contributors.length;
-  }
