diff --git a/lib/rate-limit.ts b/lib/rate-limit.ts
new file mode 100644
index 0000000..06ba094
--- /dev/null
+++ b/lib/rate-limit.ts
@@ -0,0 +1,44 @@
+/**
+ * Best-effort in-memory rate limiter for Next.js route handlers.
+ *
+ * On Vercel Fluid Compute, function instances are reused across requests, so a
+ * per-instance fixed-window Map provides real (if not globally-consistent)
+ * throttling — enough to blunt abuse of unauthenticated endpoints like the
+ * post-checkout reconcile route. For strict cross-instance limits, back this
+ * with Upstash/Redis; this needs no external dependency.
+ */
+
+type Bucket = { count: number; resetAt: number }
+const buckets = new Map<string, Bucket>()
+let lastPrune = 0
+
+function prune(now: number) {
+  // Cheap periodic cleanup so the map can't grow unbounded from unique keys.
+  if (now - lastPrune < 60_000) return
+  lastPrune = now
+  for (const [k, b] of buckets) if (now >= b.resetAt) buckets.delete(k)
+}
+
+export function rateLimit(
+  key: string,
+  opts: { max: number; windowMs: number }
+): { ok: boolean; retryAfterSec: number } {
+  const now = Date.now()
+  prune(now)
+  const b = buckets.get(key)
+  if (!b || now >= b.resetAt) {
+    buckets.set(key, { count: 1, resetAt: now + opts.windowMs })
+    return { ok: true, retryAfterSec: 0 }
+  }
+  if (b.count >= opts.max) {
+    return { ok: false, retryAfterSec: Math.max(1, Math.ceil((b.resetAt - now) / 1000)) }
+  }
+  b.count++
+  return { ok: true, retryAfterSec: 0 }
+}
+
+/** Client IP from the standard proxy headers (Vercel sets x-forwarded-for). */
+export function clientIp(request: Request): string {
+  const xff = request.headers.get('x-forwarded-for')
+  return xff?.split(',')[0]?.trim() || request.headers.get('x-real-ip') || 'unknown'
+}

