-  }
-
-  /**
-   * Validate environment variables are properly configured
-   */
-  validateEnvironment(): { valid: boolean; errors: string[] } {
-    const errors: string[] = []
-
-    // Check required environment variables
-    const required = [
-      'NEXT_PUBLIC_SUPABASE_URL',
-      'NEXT_PUBLIC_SUPABASE_ANON_KEY', 
-      'SUPABASE_SERVICE_ROLE_KEY'
-    ]
-
-    if (this.config.requireMcpToken) {
-      required.push('MCP_TOKEN')
-    }
-
-    for (const envVar of required) {
-      if (!process.env[envVar]) {
-        errors.push(`Missing required environment variable: ${envVar}`)
-      }
-    }
-
-    // Check for insecure development tokens in production
-    if (process.env.NODE_ENV === 'production') {
-      const insecureTokens = ['dev-token', 'test-token', 'development']
-      
-      for (const [key, value] of Object.entries(process.env)) {
-        if (key.includes('TOKEN') || key.includes('KEY') || key.includes('SECRET')) {
-          if (insecureTokens.some(token => value?.includes(token))) {
-            errors.push(`Insecure token detected in production environment: ${key}`)
-          }
-        }
-      }
-    }
-
-    // Validate URLs
-    if (process.env.NEXT_PUBLIC_SUPABASE_URL && !this.isValidUrl(process.env.NEXT_PUBLIC_SUPABASE_URL)) {
-      errors.push('Invalid NEXT_PUBLIC_SUPABASE_URL format')
