-      )
-    }
-
-    // HTTPS enforcement in production
-    if (this.config.enforceHttps && !this.isHttps(request)) {
-      return NextResponse.json(
-        { error: 'HTTPS required' },
-        { status: 403 }
-      )
-    }
-
-    // Origin validation
-    if (this.config.validateOrigin && !this.isValidOrigin(request)) {
-      return NextResponse.json(
-        { error: 'Invalid origin' },
-        { status: 403 }
-      )
-    }
-
-    // MCP Token validation
-    if (this.config.requireMcpToken && !this.hasValidMcpToken(request)) {
-      return NextResponse.json(
-        { error: 'Invalid or missing MCP token' },
-        { status: 401 }
-      )
-    }
-
-    // Add security headers
-    const response = NextResponse.next()
-    this.addSecurityHeaders(response)
-    
-    return null // Continue processing
-  }
-
-  /**
-   * Check if request has valid MCP token (timing-safe comparison)
-   */
-  private hasValidMcpToken(request: NextRequest): boolean {
-    const authHeader = request.headers.get('authorization')
-    const internalSecret = request.headers.get('x-internal-secret')
-    const validToken = process.env.MCP_TOKEN
-
-    if (!validToken) {
-      console.error('MCP_TOKEN not configured in environment')
-      return false
-    }
-
-    // Check Authorization header
-    if (authHeader?.startsWith('Bearer ')) {
-      const token = authHeader.slice(7)
-      return this.safeCompare(token, validToken)
-    }
-
-    // Check internal secret header (for server-to-server calls)
-    if (internalSecret) {
-      return this.safeCompare(internalSecret, validToken)
-    }
-
-    return false
-  }
-
-  /**
-   * Constant-time string comparison to prevent timing attacks
-   */
-  private safeCompare(a: string, b: string): boolean {
-    if (a.length !== b.length) return false
-    try {
-      return timingSafeEqual(Buffer.from(a), Buffer.from(b))
-    } catch {
-      return false
-    }
-  }
-
-  /**
