-    }
-  }
-
-  /**
-   * Validate URL format
-   */
-  private isValidUrl(url: string): boolean {
-    try {
-      new URL(url)
-      return true
-    } catch {
-      return false
-    }
-  }
-}
-
-// Export singleton instance
-export const securityMiddleware = new SecurityMiddleware()
