+/**
+ * `vasperamemory context` — assembles a token-budgeted governed-context block
+ * for the current repo. This is the payload the Claude Code SessionStart hook
+ * injects (Differentiation Spec Phase 1 §3.1).
+ *
+ * The CLI owns budgeting (tiktoken via token-metrics) so output is deterministic
+ * and identical for hosted and --local mode: two data sources feed ONE renderer.
+ */
+
+import { countTokens } from './token-metrics.js';
+
+export interface ContextEntry {
+  id: string;
+  seq?: number | null;
+  pillar?: string;
+  kind?: string;
+  title?: string | null;
+  body?: unknown; // pillar-shaped payload (object, or JSON string in local mode)
+  content?: string | null; // decisions
+  reasoning?: string | null;
+  category?: string | null;
+  status?: string | null;
+  governed?: boolean;
+  created_by_agent?: string | null;
+  created_at?: string | null;
+}
+
+export interface SessionSummary {
+  summary?: string | null;
+  next_steps?: string | null;
+  ended_at?: string | null;
+}
+
+export interface ContextData {
+  system: ContextEntry[];
+  domain: ContextEntry[];
+  patterns: ContextEntry[];
+  decisions: ContextEntry[];
+  lastSession: SessionSummary | null;
+  pendingCount: number;
+}
+
+export interface GovernanceCtx {
+  mode: 'cloud' | 'local';
+  projectId: string;
+  apiKey?: string;
+  serverUrl?: string;
+  dataDir?: string;
+}
+
+/** Fetch the raw context pieces from the right source (hosted REST or local SQLite). */
+export async function fetchContextData(ctx: GovernanceCtx): Promise<ContextData> {
+  if (ctx.mode === 'cloud') {
+    const url = `${ctx.serverUrl}/v1/context/raw?projectId=${encodeURIComponent(ctx.projectId)}`;
+    const res = await fetch(url, { headers: { Authorization: `Bearer ${ctx.apiKey}` } });
+    if (!res.ok) {
+      throw new Error(`context fetch failed: ${res.status} ${await res.text().catch(() => '')}`);
+    }
+    const d = (await res.json()) as Partial<ContextData>;
+    return {
+      system: d.system ?? [],
+      domain: d.domain ?? [],
+      patterns: d.patterns ?? [],
+      decisions: d.decisions ?? [],
+      lastSession: d.lastSession ?? null,
+      pendingCount: d.pendingCount ?? 0,
+    };
+  }
+  const { getLocalDatabase } = await import('./local-db.js');
+  const { initGovernanceSchema } = await import('./governance/local-gate.js');
+  const db = getLocalDatabase(ctx.dataDir).rawDb;
+  initGovernanceSchema(db);
+  return fetchLocalContextData(db, ctx.projectId);
+}
+
+/** Build the same ContextData shape from the local SQLite governance tables. */
+export function fetchLocalContextData(db: any, projectId: string): ContextData {
+  const since = new Date(Date.now() - 30 * 86_400_000).toISOString();
+  const entries: any[] = db
+    .prepare(
+      "SELECT id, pillar, kind, title, body, status, created_by_agent, created_at FROM pillar_entries WHERE project_id=? AND status='active' AND pillar IN ('system','domain','pattern') ORDER BY created_at DESC LIMIT 200"
+    )
+    .all(projectId);
+  const seqRows: any[] = db
+    .prepare("SELECT ref_id, seq FROM governance_ledger WHERE project_id=? AND event_type='commit'")
+    .all(projectId);
+  const seqByRef: Record<string, number> = {};
+  for (const r of seqRows) if (r.ref_id) seqByRef[r.ref_id] = r.seq;
+  const withSeq = (rows: any[]): ContextEntry[] => rows.map((r) => ({ ...r, seq: seqByRef[r.id] ?? null }));
+  const byPillar = (p: string) => withSeq(entries.filter((e) => e.pillar === p));
+
+  let decisions: ContextEntry[] = [];
+  try {
+    decisions = withSeq(
+      db
+        .prepare(
+          'SELECT id, title, content, reasoning, category, created_by_agent, created_at FROM decisions WHERE project_id=? AND created_at>=? ORDER BY created_at DESC LIMIT 50'
+        )
+        .all(projectId, since)
+    );
+  } catch {
+    /* decisions table may be absent in older local DBs */
+  }
+  let pendingCount = 0;
+  try {
+    const row: any = db
+      .prepare("SELECT COUNT(*) AS c FROM memory_proposals WHERE project_id=? AND status='pending'")
+      .get(projectId);
+    pendingCount = row?.c ?? 0;
+  } catch {
+    /* ignore */
+  }
+
+  return {
+    system: byPillar('system'),
+    domain: byPillar('domain'),
+    patterns: byPillar('pattern'),
+    decisions,
+    lastSession: null, // local session summaries land with Phase 1 PR-2 (session-end)
+    pendingCount,
+  };
+}
+
+export interface RenderOpts {
+  budget?: number;
+  format?: 'markdown' | 'json';
+  pillar?: string; // filter to a single pillar
+}
+
+function asBody(b: unknown): Record<string, any> {
+  if (b == null) return {};
+  if (typeof b === 'string') {
+    try {
+      return JSON.parse(b);
+    } catch {
+      return { _text: b };
+    }
+  }
+  return b as Record<string, any>;
+}
+
+/** Provenance suffix: `#142 · claude-code · 2026-08-12` (+ [ungoverned] when legacy). */
+function prov(e: ContextEntry): string {
+  const seq = e.seq != null ? `#${e.seq} · ` : '';
+  const agent = e.created_by_agent || 'unknown';
+  const date = (e.created_at || '').slice(0, 10);
+  const ungoverned = e.governed === false ? ' [ungoverned]' : '';
+  return `(${seq}${agent}${date ? ` · ${date}` : ''})${ungoverned}`;
+}
+
+function oneLine(s: unknown, max = 200): string {
+  const t = String(s ?? '').replace(/\s+/g, ' ').trim();
+  return t.length > max ? t.slice(0, max - 1) + '…' : t;
+}
+
+/**
+ * Deterministic, token-budgeted markdown (or json) rendering. Priority order:
+ * System → Domain → recent Decisions → Patterns → last session → pending count.
+ * No live timestamps in the output, so a fixed ContextData renders byte-identically.
+ */
+export function renderContext(data: ContextData, opts: RenderOpts = {}): string {
+  const budget = opts.budget ?? 1200;
+  const format = opts.format ?? 'markdown';
+
+  const view: ContextData = opts.pillar
+    ? {
+        system: opts.pillar === 'system' ? data.system : [],
+        domain: opts.pillar === 'domain' ? data.domain : [],
+        patterns: opts.pillar === 'pattern' ? data.patterns : [],
+        decisions: opts.pillar === 'decision' ? data.decisions : [],
+        lastSession: data.lastSession,
+        pendingCount: data.pendingCount,
+      }
+    : data;
+
+  if (format === 'json') {
+    return JSON.stringify(view);
+  }
+
+  const out: string[] = [];
+  let used = 0;
+  const push = (line: string): boolean => {
+    const t = countTokens(line + '\n');
+    if (used + t > budget) return false;
+    out.push(line);
+    used += t;
+    return true;
+  };
+
+  push('# VasperaMemory — governed context');
+
+  const section = (heading: string, items: ContextEntry[], fmt: (e: ContextEntry) => string): boolean => {
+    if (!items.length) return true;
+    if (!push('')) return false;
+    if (!push(`## ${heading}`)) return false;
+    for (const it of items) {
+      if (!push(fmt(it))) return false;
+    }
+    return true;
+  };
+
+  const sysFmt = (e: ContextEntry) => {
+    const b = asBody(e.body);
+    const name = b.component || e.title || '(system)';
+    const rule = b.forbidden_deps?.length
+      ? `forbids ${(b.forbidden_deps as string[]).join(', ')}`
+      : b.allowed_deps?.length
+        ? `allows ${(b.allowed_deps as string[]).join(', ')}`
+        : oneLine(b.description);
+    return `- **${name}** — ${oneLine(rule)} ${prov(e)}`;
+  };
+  const domFmt = (e: ContextEntry) => {
+    const b = asBody(e.body);
+    return `- **${b.rule_key || e.title || '(domain)'}** — ${oneLine(b.statement || b.description)} ${prov(e)}`;
+  };
+  const patFmt = (e: ContextEntry) => {
+    const b = asBody(e.body);
+    const tag = b.kind === 'anti' ? '⛔ ' : '';
+    return `- ${tag}**${b.name || e.title || '(pattern)'}** — ${oneLine(b.description)} ${prov(e)}`;
+  };
+  const decFmt = (e: ContextEntry) => `- **${oneLine(e.title, 120)}** — ${oneLine(e.content)} ${prov(e)}`;
+
+  // Priority order; stop as soon as the budget is exhausted.
+  section('System boundaries', view.system, sysFmt) &&
+    section('Domain rules', view.domain, domFmt) &&
+    section('Recent decisions', view.decisions, decFmt) &&
+    section('Patterns', view.patterns, patFmt);
+
+  if (view.lastSession?.summary) {
+    push('');
+    push('## Last session');
+    push(`- ${oneLine(view.lastSession.summary, 300)}`);
+    if (view.lastSession.next_steps) push(`- Next: ${oneLine(view.lastSession.next_steps, 200)}`);
+  }
+
+  if (view.pendingCount > 0) {
+    push('');
+    push(`> ${view.pendingCount} pending proposal${view.pendingCount === 1 ? '' : 's'} — run \`vasperamemory review\`.`);
+  }
+
+  return out.join('\n');
+}
