+/**
+ * Heuristic decision extractor for `vasperamemory session-end` (Phase 1 §3.2).
+ *
+ * No LLM, no cost: regex heuristics over transcript text, mirroring the patterns
+ * in server/chat-intelligence.ts. Produces Decision-pillar proposal candidates.
+ * Precision over recall — a wrong proposal costs a human a reject click, so the
+ * patterns are deliberately conservative and de-duplicated.
+ */
+
+export type DecisionCategory =
+  | 'architectural'
+  | 'pattern'
+  | 'convention'
+  | 'fix'
+  | 'rejection'
+  | 'preference';
+
+export interface ExtractedCandidate {
+  title: string;
+  decision: string;
+  reasoning?: string;
+  category: DecisionCategory;
+  confidence: number; // 0..0.95
+}
+
+interface Rule {
+  re: RegExp;
+  category: DecisionCategory;
+  base: number;
+}
+
+// Ordered by specificity; the first match on a line wins.
+const RULES: Rule[] = [
+  { re: /^\s*(?:remember|decision|note)\s*:\s*(.+)/i, category: 'architectural', base: 0.8 },
+  { re: /\bwe (?:decided|agreed)(?: to| that)? (.+)/i, category: 'architectural', base: 0.72 },
+  { re: /\b(?:decided|agreeing) against (.+)/i, category: 'rejection', base: 0.72 },
+  { re: /\b(?:going with|we're going with|let's go with|let's use|we'll use|switched to|migrated to) (.+)/i, category: 'architectural', base: 0.62 },
+  { re: /\b(?:do not|don't|never|do not ever) use (.+)/i, category: 'rejection', base: 0.66 },
+  { re: /\b(?:always|never) (.+)/i, category: 'convention', base: 0.55 },
+  { re: /\bprefer (.+?) over (.+)/i, category: 'preference', base: 0.62 },
+];
+
+const REASONING_RES: RegExp[] = [
+  /\bbecause (.+)/i,
+  /\bsince (.+)/i,
+  /\bso that (.+)/i,
+  /\bthe (?:reason|rationale) is (.+)/i,
+  /\bto avoid (.+)/i,
+];
+
+function clean(s: string): string {
+  return s
+    .replace(/[`*_>#]+/g, '')
+    .replace(/\s+/g, ' ')
+    .replace(/[.,;:\s]+$/, '')
+    .trim();
+}
+
+function truncate(s: string, max: number): string {
+  return s.length > max ? s.slice(0, max - 1).trimEnd() + '…' : s;
+}
+
+function normKey(s: string): string {
+  return s.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
+}
+
+function extractReasoning(line: string): string | undefined {
+  for (const re of REASONING_RES) {
+    const m = line.match(re);
+    if (m && m[1]) return truncate(clean(m[1]), 300);
+  }
+  return undefined;
+}
+
+/**
+ * Extract Decision candidates from raw transcript text. Deterministic; dedupes
+ * near-identical decisions (normalized key). One candidate per matching line.
+ */
+export function extractDecisions(text: string): ExtractedCandidate[] {
+  const out: ExtractedCandidate[] = [];
+  const seen = new Set<string>();
+
+  for (const rawLine of text.split(/\r?\n/)) {
+    const line = rawLine.trim();
+    if (line.length < 8 || line.length > 600) continue;
+
+    for (const rule of RULES) {
+      const m = line.match(rule.re);
+      if (!m) continue;
+      const decision = clean(m[1] ?? line);
+      if (decision.length < 4) break;
+
+      const key = normKey(decision);
+      if (!key || seen.has(key)) break;
+      seen.add(key);
+
+      const reasoning = extractReasoning(line);
+      let confidence = rule.base;
+      if (/^\s*(?:remember|decision)\s*:/i.test(line)) confidence += 0.1;
+      if (reasoning) confidence += 0.05;
+      confidence = Math.min(0.95, Math.round(confidence * 100) / 100);
+
+      out.push({
+        title: truncate(decision, 120),
+        decision,
+        reasoning,
+        category: rule.category,
+        confidence,
+      });
+      break; // one candidate per line
+    }
+  }
+  return out;
+}
