+/**
+ * Local (SQLite) session summaries — the local mirror of the hosted `ai_sessions`
+ * table, so `vasperamemory context` can show "last session" in --local mode and
+ * `session-end` can persist a summary offline. (Phase 1 §3.2.)
+ */
+import { randomUUID } from 'crypto';
+
+export function ensureSessionsTable(db: any): void {
+  db.exec(
+    `CREATE TABLE IF NOT EXISTS ai_sessions (
+       id TEXT PRIMARY KEY,
+       project_id TEXT NOT NULL,
+       session_id TEXT,
+       summary TEXT,
+       next_steps TEXT,
+       ended_at TEXT,
+       created_at TEXT
+     )`
+  );
+}
+
+export function saveLocalSession(
+  db: any,
+  s: { projectId: string; sessionId?: string; summary: string; nextSteps?: string }
+): void {
+  ensureSessionsTable(db);
+  const now = new Date().toISOString();
+  db.prepare(
+    'INSERT INTO ai_sessions (id, project_id, session_id, summary, next_steps, ended_at, created_at) VALUES (?,?,?,?,?,?,?)'
+  ).run(randomUUID(), s.projectId, s.sessionId ?? null, s.summary, s.nextSteps ?? null, now, now);
+}
+
+export function getLastLocalSession(
+  db: any,
+  projectId: string
+): { summary: string; next_steps: string | null; ended_at: string } | null {
+  ensureSessionsTable(db);
+  const row = db
+    .prepare(
+      "SELECT summary, next_steps, ended_at FROM ai_sessions WHERE project_id=? AND ended_at IS NOT NULL ORDER BY ended_at DESC LIMIT 1"
+    )
+    .get(projectId);
+  return row ?? null;
+}
