@@ -0,0 +1,152 @@
+/**
+ * `vasperamemory session-end` — the Claude Code Stop-hook handler (Phase 1 §3.2).
+ *
+ * Reads the hook's stdin JSON ({ transcript_path, session_id, cwd, … }), parses
+ * the transcript, heuristically extracts decisions, and files them as PROPOSALS
+ * (never commits — the gate decides). Also saves a session summary. Idempotent
+ * per transcript-content hash. Never throws into the hook: failures are quiet.
+ */
+import fs from 'fs';
+import path from 'path';
+import crypto from 'crypto';
+import { extractDecisions, type ExtractedCandidate } from './extract.js';
+import { saveLocalSession } from './local-sessions.js';
+import type { GovernanceCtx } from './context.js';
+
+/** Extract human/assistant text from a Claude Code transcript (JSONL, or a single JSON array). */
+export function parseTranscriptText(raw: string): string {
+  const texts: string[] = [];
+  const pushContent = (content: unknown) => {
+    if (typeof content === 'string') texts.push(content);
+    else if (Array.isArray(content)) {
+      for (const block of content) {
+        if (block && typeof block === 'object' && (block as any).type === 'text' && typeof (block as any).text === 'string') {
+          texts.push((block as any).text);
+        }
+      }
+    }
+  };
+  const handleObj = (obj: any) => {
+    const msg = obj?.message ?? obj;
+    if (msg?.content !== undefined) pushContent(msg.content);
+  };
+
+  const trimmed = raw.trim();
+  if (trimmed.startsWith('[')) {
+    try {
+      const arr = JSON.parse(trimmed);
+      if (Array.isArray(arr)) arr.forEach(handleObj);
+      return texts.join('\n');
+    } catch {
+      /* fall through to JSONL */
+    }
+  }
+  for (const line of raw.split('\n')) {
+    if (!line.trim()) continue;
+    try {
+      handleObj(JSON.parse(line));
+    } catch {
+      /* skip malformed lines */
+    }
+  }
+  return texts.join('\n');
+}
+
+async function proposeCandidate(ctx: GovernanceCtx, c: ExtractedCandidate): Promise<void> {
+  const payload = { title: c.title, decision: c.decision, category: c.category };
+  if (ctx.mode === 'cloud') {
+    const res = await fetch(`${ctx.serverUrl}/v1/governance/propose`, {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${ctx.apiKey}` },
+      body: JSON.stringify({ projectId: ctx.projectId, pillar: 'decision', payload, reasoning: c.reasoning, agent: 'claude-code' }),
+    });
+    if (!res.ok) throw new Error(`propose ${res.status}`);
+    return;
+  }
+  const { getLocalDatabase } = await import('./local-db.js');
+  const { localPropose } = await import('./governance/local-gate.js');
+  const db = getLocalDatabase(ctx.dataDir).rawDb;
+  localPropose(db, { projectId: ctx.projectId, pillar: 'decision', payload, reasoning: c.reasoning, agent: 'claude-code' });
+}
+
+async function saveSession(ctx: GovernanceCtx, summary: string, sessionId?: string): Promise<void> {
+  if (ctx.mode === 'cloud') {
+    await fetch(`${ctx.serverUrl}/v1/sessions`, {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${ctx.apiKey}` },
+      body: JSON.stringify({ projectId: ctx.projectId, summary, sessionId }),
+    }).catch(() => {});
+    return;
+  }
+  const { getLocalDatabase } = await import('./local-db.js');
+  const db = getLocalDatabase(ctx.dataDir).rawDb;
+  saveLocalSession(db, { projectId: ctx.projectId, summary, sessionId });
+}
+
+export interface SessionEndResult {
+  proposed: number;
+  skipped: boolean; // true when deduped or no transcript
+  reason?: string;
+}
+
+export async function runSessionEnd(
+  ctx: GovernanceCtx,
+  opts: { transcriptPath?: string; sessionId?: string }
+): Promise<SessionEndResult> {
+  if (!opts.transcriptPath || !fs.existsSync(opts.transcriptPath)) {
+    return { proposed: 0, skipped: true, reason: 'no transcript' };
+  }
+  const raw = fs.readFileSync(opts.transcriptPath, 'utf8');
+  const hash = crypto.createHash('sha256').update(raw).digest('hex');
+
+  const stateDir = path.join(process.cwd(), '.vasperamemory');
+  const stateFile = path.join(stateDir, 'transcripts.json');
+  let seen: string[] = [];
+  try {
+    seen = JSON.parse(fs.readFileSync(stateFile, 'utf8'));
+  } catch {
+    /* no state yet */
+  }
+  if (seen.includes(hash)) return { proposed: 0, skipped: true, reason: 'already processed' };
+
+  const candidates = extractDecisions(parseTranscriptText(raw));
+  let proposed = 0;
+  for (const c of candidates) {
+    try {
+      await proposeCandidate(ctx, c);
+      proposed++;
+    } catch {
+      /* skip a single failed proposal; keep going */
+    }
+  }
+
+  const summary =
+    proposed > 0
+      ? `${proposed} decision${proposed === 1 ? '' : 's'} captured from a Claude Code session`
+      : 'Claude Code session ended (no decisions captured)';
+  await saveSession(ctx, summary, opts.sessionId).catch(() => {});
+
+  try {
+    fs.mkdirSync(stateDir, { recursive: true });
+    seen.push(hash);
+    fs.writeFileSync(stateFile, JSON.stringify(seen.slice(-500)));
+  } catch {
+    /* best-effort dedupe state */
+  }
+
+  return { proposed, skipped: false };
+}
+
+/** Read the hook's stdin JSON payload (best-effort; returns {} if none). */
+export async function readHookStdin(): Promise<{ transcript_path?: string; session_id?: string; cwd?: string }> {
+  if (process.stdin.isTTY) return {};
+  const chunks: Buffer[] = [];
+  for await (const chunk of process.stdin) chunks.push(chunk as Buffer);
+  const raw = Buffer.concat(chunks).toString('utf8').trim();
+  if (!raw) return {};
+  try {
+    return JSON.parse(raw);
+  } catch {
+    return {};
+  }
+}
