diff --git a/packages/cli/src/claude-hooks.ts b/packages/cli/src/claude-hooks.ts
new file mode 100644
index 0000000..116d109
--- /dev/null
+++ b/packages/cli/src/claude-hooks.ts
@@ -0,0 +1,125 @@
+/**
+ * Claude Code hooks installer (Phase 1 §3.3) — wires the zero-effort loop into
+ * `.claude/settings.json`:
+ *   SessionStart → vasperamemory context --format markdown
+ *   PreCompact   → vasperamemory context --budget 600
+ *   Stop         → vasperamemory session-end
+ *
+ * Merges (never clobbers), backs up the prior file, and tags our entries by their
+ * `vasperamemory` command prefix so uninstall removes ONLY what we added.
+ */
+import fs from 'fs';
+import path from 'path';
+import os from 'os';
+import { execSync } from 'child_process';
+
+const MARKER = 'vasperamemory'; // our hook commands start with this
+
+export const CLAUDE_HOOKS: { event: string; command: string }[] = [
+  { event: 'SessionStart', command: 'vasperamemory context --format markdown' },
+  { event: 'PreCompact', command: 'vasperamemory context --budget 600' },
+  { event: 'Stop', command: 'vasperamemory session-end' },
+];
+
+export function claudeSettingsPath(global = false): string {
+  return global
+    ? path.join(os.homedir(), '.claude', 'settings.json')
+    : path.join(process.cwd(), '.claude', 'settings.json');
+}
+
+function readSettings(p: string): any {
+  try {
+    return JSON.parse(fs.readFileSync(p, 'utf8'));
+  } catch {
+    return {};
+  }
+}
+
+function writeSettings(p: string, settings: any): void {
+  // Deleting an empty settings object restores the "file absent" state so an
+  // install→uninstall round-trip is byte-identical when we created the file.
+  if (settings && typeof settings === 'object' && Object.keys(settings).length === 0) {
+    if (fs.existsSync(p)) fs.rmSync(p);
+    return;
+  }
+  fs.writeFileSync(p, JSON.stringify(settings, null, 2) + '\n');
+}
+
+/** A matcher-group is ours if any of its command hooks starts with `vasperamemory`. */
+function isOurs(group: any): boolean {
+  return (
+    Array.isArray(group?.hooks) &&
+    group.hooks.some((h: any) => typeof h?.command === 'string' && h.command.startsWith(MARKER))
+  );
+}
+
+export interface InstallResult {
+  installed: string[];
+  settingsPath: string;
+  backedUp: boolean;
+}
+
+export function installClaudeHooks(opts: { global?: boolean } = {}): InstallResult {
+  const p = claudeSettingsPath(opts.global);
+  fs.mkdirSync(path.dirname(p), { recursive: true });
+  let backedUp = false;
+  if (fs.existsSync(p)) {
+    fs.copyFileSync(p, p + '.backup');
+    backedUp = true;
+  }
+  const settings = fs.existsSync(p) ? readSettings(p) : {};
+  settings.hooks = settings.hooks || {};
+  const installed: string[] = [];
+  for (const h of CLAUDE_HOOKS) {
+    const arr: any[] = Array.isArray(settings.hooks[h.event]) ? settings.hooks[h.event] : [];
+    const kept = arr.filter((g) => !isOurs(g)); // idempotent: drop our prior entry first
+    kept.push({ hooks: [{ type: 'command', command: h.command }] });
+    settings.hooks[h.event] = kept;
+    installed.push(h.event);
+  }
+  writeSettings(p, settings);
+  return { installed, settingsPath: p, backedUp };
+}
+
+export function uninstallClaudeHooks(opts: { global?: boolean } = {}): { removed: number; settingsPath: string } {
+  const p = claudeSettingsPath(opts.global);
+  if (!fs.existsSync(p)) return { removed: 0, settingsPath: p };
+  const settings = readSettings(p);
+  let removed = 0;
+  if (settings.hooks && typeof settings.hooks === 'object') {
+    for (const event of Object.keys(settings.hooks)) {
+      const arr = settings.hooks[event];
+      if (!Array.isArray(arr)) continue;
+      const before = arr.length;
+      const kept = arr.filter((g: any) => !isOurs(g));
+      removed += before - kept.length;
+      if (kept.length === 0) delete settings.hooks[event];
+      else settings.hooks[event] = kept;
+    }
+    if (Object.keys(settings.hooks).length === 0) delete settings.hooks;
+  }
+  writeSettings(p, settings);
+  return { removed, settingsPath: p };
+}
+
+export function claudeHooksStatus(opts: { global?: boolean } = {}): {
+  settingsPath: string;
+  installed: string[];
+  binaryResolves: boolean;
+} {
+  const p = claudeSettingsPath(opts.global);
+  const settings = fs.existsSync(p) ? readSettings(p) : {};
+  const installed: string[] = [];
+  for (const h of CLAUDE_HOOKS) {
+    const arr = settings.hooks?.[h.event];
+    if (Array.isArray(arr) && arr.some(isOurs)) installed.push(h.event);
+  }
+  let binaryResolves = false;
+  try {
+    execSync('command -v vasperamemory', { stdio: 'ignore' });
+    binaryResolves = true;
+  } catch {
+    binaryResolves = false;
+  }
+  return { settingsPath: p, installed, binaryResolves };
+}
