@@ -0,0 +1,134 @@
+/**
+ * Local (SQLite) governance READ tools — parity with the hosted handlers in
+ * server/tools/governance-tools.ts (Phase 2 §4.1). Pure functions returning the
+ * same markdown shape; the local MCP server wraps them in tool results.
+ *
+ * Governed tables (local): pillar_entries (pattern/domain/system), decisions,
+ * governance_ledger. Reads only — no writes (writes go through the gate).
+ */
+
+function clampLimit(n: unknown): number {
+  const x = Number(n) || 10;
+  return Math.min(Math.max(Math.trunc(x), 1), 50);
+}
+
+function likeArg(s: unknown): string {
+  return `%${String(s).replace(/[%_]/g, '').trim()}%`;
+}
+
+export function localQueryDecisions(db: any, projectId: string, args: any = {}): string {
+  const limit = clampLimit(args.limit);
+  const hasTopic = typeof args.topic === 'string' && args.topic.trim();
+  const rows: any[] = hasTopic
+    ? db
+        .prepare(
+          'SELECT id, title, content, reasoning, category, created_at FROM decisions WHERE project_id=? AND (title LIKE ? OR content LIKE ?) ORDER BY created_at DESC LIMIT ?'
+        )
+        .all(projectId, likeArg(args.topic), likeArg(args.topic), limit)
+    : db
+        .prepare(
+          'SELECT id, title, content, reasoning, category, created_at FROM decisions WHERE project_id=? ORDER BY created_at DESC LIMIT ?'
+        )
+        .all(projectId, limit);
+
+  if (!rows.length) {
+    return `# Decisions\n\nNo decisions on record${hasTopic ? ` for "${args.topic}"` : ''}. Cite nothing — do not invent precedent.`;
+  }
+  let out = `# Decisions on the record (${rows.length})\n\nCite decision IDs when acting on these.\n\n`;
+  for (const d of rows) {
+    out += `## ${d.title} \`decision:${String(d.id).slice(0, 8)}\`\n${d.content}\n`;
+    if (d.reasoning) out += `*Why: ${d.reasoning}*\n`;
+    out += `${d.category ?? 'uncategorized'} · ${d.created_at}\n\n`;
+  }
+  return out;
+}
+
+export function localPillarRead(
+  db: any,
+  projectId: string,
+  pillar: 'pattern' | 'domain' | 'system',
+  args: any = {}
+): string {
+  const limit = clampLimit(args.limit);
+  let sql =
+    'SELECT id, kind, title, body, status, created_by_agent, created_at FROM pillar_entries WHERE project_id=? AND pillar=? AND status=? ';
+  const params: any[] = [projectId, pillar, 'active'];
+  if (args.kind) {
+    sql += 'AND kind=? ';
+    params.push(args.kind);
+  }
+  if (typeof args.query === 'string' && args.query.trim()) {
+    sql += 'AND title LIKE ? ';
+    params.push(likeArg(args.query));
+  }
+  sql += 'ORDER BY created_at DESC LIMIT ?';
+  params.push(limit);
+  const rows: any[] = db.prepare(sql).all(...params);
+
+  if (!rows.length) return `# ${pillar}\n\nNothing on record. Do not assume unwritten ${pillar} rules.`;
+  let out = `# ${pillar} entries on the record (${rows.length})\n\n`;
+  for (const e of rows) {
+    let body: unknown;
+    try {
+      body = JSON.parse(e.body);
+    } catch {
+      body = e.body;
+    }
+    out += `## ${e.title} \`${pillar}:${String(e.id).slice(0, 8)}\` (${e.kind})\n`;
+    out += '```json\n' + JSON.stringify(body, null, 2) + '\n```\n';
+    out += `${e.created_by_agent ?? 'unattributed'} · ${e.created_at}\n\n`;
+  }
+  return out;
+}
+
+export function localCheckBoundary(db: any, projectId: string, args: any = {}): string {
+  const from = String(args.from_component ?? '').trim().toLowerCase();
+  const to = String(args.to_component ?? '').trim().toLowerCase();
+  if (!from || !to) return 'check_boundary requires from_component and to_component.';
+
+  const rows: any[] = db
+    .prepare("SELECT id, title, body FROM pillar_entries WHERE project_id=? AND pillar='system' AND status='active' LIMIT 200")
+    .all(projectId);
+  for (const e of rows) {
+    let body: any;
+    try {
+      body = JSON.parse(e.body);
+    } catch {
+      body = {};
+    }
+    if (String(body.component ?? '').trim().toLowerCase() !== from) continue;
+    const matches = (list?: string[]) =>
+      (list ?? []).some((d) => {
+        const dep = String(d).trim().toLowerCase();
+        return dep === to || (dep.endsWith('*') && to.startsWith(dep.slice(0, -1)));
+      });
+    const id = String(e.id).slice(0, 8);
+    if (matches(body.forbidden_deps)) {
+      return `# Boundary: FORBIDDEN\n\n\`${from}\` → \`${to}\` is forbidden by \`system:${id}\` (${e.title}). Do not add this dependency.`;
+    }
+    if (matches(body.allowed_deps)) {
+      return `# Boundary: ALLOWED\n\n\`${from}\` → \`${to}\` is explicitly allowed by \`system:${id}\` (${e.title}).`;
+    }
+    return `# Boundary: UNSPECIFIED\n\n\`${from}\` has a system entry (\`system:${id}\`) but \`${to}\` is neither allowed nor forbidden. Flag this to the human rather than assuming.`;
+  }
+  return `# Boundary: UNKNOWN\n\nNo system entry for \`${from}\`. The boundary is not on record — propose one via propose_entry (pillar: system).`;
+}
+
+export function localGetProvenance(db: any, projectId: string, args: any = {}): string {
+  const entryId = String(args.entry_id ?? '').trim();
+  if (!entryId) return 'get_provenance requires entry_id (full UUID).';
+  const rows: any[] = db
+    .prepare(
+      'SELECT seq, event_type, pillar, author_user, author_agent, ts, entry_hash, prev_hash, ref_table FROM governance_ledger WHERE project_id=? AND ref_id=? ORDER BY seq'
+    )
+    .all(projectId, entryId);
+  if (!rows.length) {
+    return `# Provenance\n\nNo ledger events reference \`${entryId}\`. Entries from the pre-gate era have no chain position — say so rather than inventing one.`;
+  }
+  let out = `# Provenance for \`${entryId}\`\n\n| seq | event | author | agent | ts | hash |\n|---|---|---|---|---|---|\n`;
+  for (const e of rows) {
+    out += `| ${e.seq} | ${e.event_type} | ${e.author_user ? String(e.author_user).slice(0, 8) : '—'} | ${e.author_agent ?? '—'} | ${e.ts} | \`${String(e.entry_hash).slice(7, 19)}…\` |\n`;
+  }
+  out += `\nVerify the full chain: \`npx vasperamemory verify\``;
+  return out;
+}
