diff --git a/packages/cli/src/governance/verify-output.ts b/packages/cli/src/governance/verify-output.ts
new file mode 100644
index 0000000..34fc892
--- /dev/null
+++ b/packages/cli/src/governance/verify-output.ts
@@ -0,0 +1,52 @@
+// Stable, machine-readable shapes for `vasperamemory verify --json` / `--badge`
+// (Differentiation Spec §4.5). These schemas are a PUBLIC contract — a team may
+// wire them into their own CI or badge their README — so field names and types
+// are frozen; add fields, never rename or repurpose. A unit test pins the shape.
+import type { VerifyResult } from './ledger';
+
+/** `verify --json` — the full result a CI job or dashboard consumes. */
+export interface VerifyJson {
+  project: string;
+  head_seq: number;
+  head_hash: string | null;
+  verified_at: string; // ISO 8601 UTC, app-assigned
+  ok: boolean;
+  first_divergence: { seq: number | null; reason: string | null } | null;
+}
+
+/** `verify --badge` — a shields.io endpoint payload (https://shields.io/endpoint). */
+export interface ShieldsBadge {
+  schemaVersion: 1;
+  label: string;
+  message: string;
+  color: string;
+}
+
+export function buildVerifyJson(input: {
+  projectId: string;
+  result: VerifyResult;
+  headSeq: number;
+  headHash: string | null;
+  verifiedAt: string;
+}): VerifyJson {
+  const { projectId, result, headSeq, headHash, verifiedAt } = input;
+  return {
+    project: projectId,
+    head_seq: headSeq,
+    head_hash: headHash,
+    verified_at: verifiedAt,
+    ok: result.valid,
+    first_divergence: result.valid
+      ? null
+      : { seq: result.firstBadSeq ?? null, reason: result.reason ?? null },
+  };
+}
+
+export function buildVerifyBadge(result: VerifyResult): ShieldsBadge {
+  return {
+    schemaVersion: 1,
+    label: 'ledger',
+    message: result.valid ? 'verified' : 'INVALID',
+    color: result.valid ? 'brightgreen' : 'red',
+  };
+}

